// Extract session cookie and uid from authentication response
const authData = $input.first().json;
const setCookie = authData.headers['set-cookie'];
const cookie = Array.isArray(setCookie)
  ? setCookie[0].split(';')[0]
  : setCookie.split(';')[0];
const uid = authData.body.result.uid;

// Paginated fetch of ALL products from Odoo
const LIMIT = 200;
let offset = 0;
let allProducts = [];

while (true) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://odoo:8069/jsonrpc',
    headers: { 'Cookie': cookie, 'Content-Type': 'application/json' },
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          'odoo_db',
          uid,
          'admin',
          'product.product',
          'search_read',
          [[]],
          {
            fields: [
              'id', 'name', 'default_code', 'barcode',
              'list_price', 'categ_id', 'type', 'sale_ok',
              'description', 'description_sale',
              'active'
            ],
            limit: LIMIT,
            offset: offset,
            context: { active_test: false }
          }
        ]
      }
    }
  });

  const products = response.result;
  allProducts = allProducts.concat(products);

  if (products.length < LIMIT) {
    break;
  }
  offset += LIMIT;
}

return [{ json: { products: allProducts, count: allProducts.length, fetchedAt: new Date().toISOString() } }];
